import Foundation
import XCTest
@testable import MacScope

/// MS-23 reserved-encoding boundary vectors. `GoldenFixtures/arm64-reserved-vectors/vectors.tsv` is
/// generated by `Scripts/arm64_golden/generate_arm64_reserved_vectors.py`: the MS-23 ledger's example
/// words plus valid seeds and their single-bit flips over each class's reserved fields, labelled by
/// Apple `llvm-objdump` in generic syntax. Where objdump rejects a word MacScope must print `unknown`
/// (never a plausible instruction); where objdump decodes it MacScope must print the same text
/// (numbers compared by value).
final class ARM64ReservedEncodingGoldenTests: XCTestCase {
    private struct Row {
        let family: String
        let address: UInt64
        let word: UInt32
        let objdump: String
    }

    private static let fixture = TestSourceRoot.fileURL(#filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("GoldenFixtures/arm64-reserved-vectors/vectors.tsv")

    /// Valid words that MacScope leaves `unknown` by policy (MS-23 ledger §6): FEAT_LSUI `ldtp`/`sttp`
    /// (out of scope) and MSR/MRS to implementation-defined `S0_*` registers.
    private static func isAcceptedGap(_ objdump: String) -> Bool {
        objdump.hasPrefix("ldtp ") || objdump.hasPrefix("sttp ") || objdump.hasPrefix("msr s0_")
            || (objdump.hasPrefix("mrs ") && objdump.contains(", s0_"))
    }

    private static func rows() throws -> [Row] {
        let text = try String(contentsOf: fixture, encoding: .utf8)
        return try text.split(separator: "\n", omittingEmptySubsequences: true)
            .filter { !$0.hasPrefix("#") }
            .map { line in
                let fields = line.components(separatedBy: "\t")
                XCTAssertEqual(fields.count, 4, "malformed row \(line)")
                return Row(
                    family: fields[0],
                    address: try XCTUnwrap(UInt64(fields[1].dropFirst(2), radix: 16)),
                    word: try XCTUnwrap(UInt32(fields[2], radix: 16)),
                    objdump: fields[3]
                )
            }
    }

    private func decode(_ word: UInt32, at address: UInt64) -> DecodedInstruction {
        let data = Data([
            UInt8(word & 0xff), UInt8((word >> 8) & 0xff), UInt8((word >> 16) & 0xff), UInt8((word >> 24) & 0xff),
        ])
        return ARM64Decoder().decode(data, baseAddress: address, maxInstructionCount: 1)[0]
    }

    /// Lower case, `{ v0 }` → `{v0}`, every number to decimal, so hex and decimal spellings compare by value.
    private static func normalized(_ text: String) -> String {
        var result = text.lowercased().replacingOccurrences(of: "{ ", with: "{").replacingOccurrences(of: " }", with: "}")
        result = result.split(separator: " ", omittingEmptySubsequences: true).joined(separator: " ")
        let pattern = try! NSRegularExpression(pattern: #"(?<![A-Za-z0-9_])(-?)(0x[0-9a-fA-F]+|[0-9]+)(?![A-Za-z0-9_])"#)
        let source = result
        for match in pattern.matches(in: source, range: NSRange(source.startIndex..., in: source)).reversed() {
            guard let whole = Range(match.range, in: result),
                  let sign = Range(match.range(at: 1), in: source),
                  let digits = Range(match.range(at: 2), in: source) else { continue }
            let token = String(source[digits])
            guard let value = token.hasPrefix("0x") ? UInt64(token.dropFirst(2), radix: 16) : UInt64(token) else { continue }
            result.replaceSubrange(whole, with: "\(source[sign])\(value)")
        }
        return result
    }

    func testReservedWordsDecodeAsUnknownAndValidNeighboursMatchObjdump() throws {
        let rows = try Self.rows()
        XCTAssertGreaterThan(rows.count, 600)
        var rejected = 0, exact = 0, gaps = 0
        for row in rows {
            let decoded = decode(row.word, at: row.address)
            let text = decoded.operands.isEmpty ? decoded.mnemonic : "\(decoded.mnemonic) \(decoded.operands)"
            let context = "\(row.family) \(String(format: "%08x", row.word)): objdump `\(row.objdump)`, MacScope `\(text)`"
            if row.objdump == "<unknown>" {
                XCTAssertEqual(decoded.mnemonic, "unknown", context)
                rejected += 1
            } else if Self.isAcceptedGap(row.objdump) {
                XCTAssertEqual(decoded.mnemonic, "unknown", context)
                gaps += 1
            } else {
                XCTAssertEqual(Self.normalized(text), Self.normalized(row.objdump), context)
                exact += 1
            }
        }
        XCTAssertGreaterThan(rejected, 150)
        XCTAssertGreaterThan(exact, 200)
        XCTAssertLessThan(gaps, 90)
    }

    /// The MS-23 ledger's real-code bugs, pinned word by word (generic objdump text).
    func testLedgerRealCodeBugs() {
        func text(_ word: UInt32) -> String {
            let d = decode(word, at: 0)
            return d.operands.isEmpty ? d.mnemonic : "\(d.mnemonic) \(d.operands)"
        }
        // Add/subtract with carry: was a fabricated store (class-1 load/store guard).
        XCTAssertEqual(text(0xfa0a_0343), "sbcs x3, x26, x10")
        XCTAssertEqual(text(0x3a1c_0264), "adcs w4, w19, w28")
        XCTAssertEqual(text(0x7a0a_0329), "sbcs w9, w25, w10")
        XCTAssertEqual(text(0xda02_03e0), "ngc x0, x2")
        XCTAssertEqual(text(0xba1f_842f), "rmif x1, #0x3f, #0xf")
        XCTAssertEqual(text(0x3a00_0400), "unknown 0x3a000400")
        XCTAssertEqual(text(0x3ba5_8780), "unknown 0x3ba58780")
        // 64-bit immediates of 2^32 and above.
        XCTAssertEqual(text(0x92c0_0020), "mov x0, #-0x100000001")
        XCTAssertEqual(text(0x92f2_a6a0), "mov x0, #0x6acaffffffffffff")
        // Vector FP compares.
        XCTAssertEqual(text(0x2e3d_e663), "fcmge v3.2s, v19.2s, v29.2s")
        XCTAssertEqual(text(0x6e75_ee3f), "facge v31.2d, v17.2d, v21.2d")
        XCTAssertEqual(text(0x6efd_efec), "facgt v12.2d, v31.2d, v29.2d")
        // Extended register: `lsl` only with SP; 32-bit forms read Wm.
        XCTAssertEqual(text(0x0b23_5294), "add w20, w20, w3, uxtw #4")
        XCTAssertEqual(text(0x2b3b_ed00), "adds w0, w8, w27, sxtx #3")
        // LSE ST alias needs A=0.
        XCTAssertEqual(text(0x78b3_137f), "ldclrah w19, wzr, [x27]")
        // Barriers need op1=011.
        XCTAssertNotEqual(decode(0xd504_339f, at: 0).mnemonic, "dsb")
        XCTAssertEqual(text(0xd503_339f), "dsb osh")
    }
}
